.gb-detail-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: 24px;
  scrollbar-gutter: stable;
}
.gb-thread-title {
  margin-bottom: 12px !important;
}
.gb-messages {
  display: flex;
  flex-direction: column;
  gap: 22px;
  margin: 24px 0;
}
.gb-messages article {
  min-width: 0;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--edge);
}
.gb-message-card {
  padding-bottom: 22px;
  border-bottom: 1px solid var(--edge);
}
.gb-message-card-header {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}
.gb-sender-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--panel);
  border: 1px solid var(--edge);
  color: var(--text);
  font-weight: 600;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  user-select: none;
}
.gb-message-header-info {
  flex: 1;
  min-width: 0;
}
.gb-sender-line {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}
.gb-sender-name {
  font-size: 13px;
  color: var(--text);
  font-weight: 600;
}
.gb-sender-email {
  font-size: 11px;
  color: var(--muted);
  font-weight: normal;
}
.gb-message-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 12px;
  align-items: center;
  justify-content: space-between;
}
.gb-message-meta time,
.gb-recipient {
  font-size: 11px;
  color: var(--muted);
}
.gb-recipient {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-top: 3px !important;
}
.gb-view-toggle {
  display: inline-flex;
  background: var(--panel);
  border: 1px solid var(--edge);
  border-radius: 6px;
  padding: 2px;
  gap: 2px;
  flex-shrink: 0;
}
.gb-view-toggle button {
  border: none;
  background: transparent;
  padding: 3px 7px;
  border-radius: 4px;
  font-size: 11px;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  line-height: 1;
}
.gb-view-toggle button:hover {
  color: var(--text);
}
.gb-view-toggle button.is-active {
  background: var(--bg);
  color: var(--text);
  font-weight: 500;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
.gb-message-content {
  margin-top: 14px;
}
.gb-plain-body {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: break-word;
  font-family: inherit;
  font-size: 14px;
  line-height: 1.65;
  color: var(--text);
}
.gb-link-chip {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
  margin: 1px 3px;
  padding: 2px 7px;
  border-radius: 4px;
  background: var(--panel);
  border: 1px solid var(--edge);
  font-size: 12px;
  line-height: 1.4;
  gap: 5px;
  max-width: 100%;
}
.gb-link-url {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #3b82f6;
  text-decoration: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gb-link-url:hover {
  text-decoration: underline;
}
.gb-link-copy-btn {
  border: none;
  background: transparent;
  padding: 2px;
  border-radius: 3px;
  color: var(--muted);
  cursor: pointer;
  display: flex;
  align-items: center;
}
.gb-link-copy-btn:hover {
  color: var(--text);
  background: rgba(127, 127, 127, 0.15);
}
.gb-email-frame {
  display: block;
  width: 100%;
  height: 320px;
  border: 0;
  background: #fff;
  color-scheme: light;
}
.gb-truncated {
  margin-top: 8px;
}
.gb-alert {
  position: absolute;
  right: 20px;
  top: 64px;
  z-index: 4;
  width: min(460px, calc(100% - 40px));
  box-shadow: 0 4px 20px #0002;
  border-radius: 8px;
}
.gb-error {
  max-width: 100%;
  border: 1px solid light-dark(#dfbaba, #704444);
  background: var(--surface);
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 12px;
  overflow: hidden;
}
.gb-detail .gb-error {
  margin-bottom: 12px;
}
.gb-error > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.gb-error > div > strong {
  font-weight: 500;
}
.gb-error button {
  padding: 4px 8px;
  font-size: 12px;
}
.gb-error summary {
  cursor: pointer;
  padding: 5px 0 0;
  color: var(--muted);
}
.gb-error textarea {
  margin-top: 10px;
  width: 100%;
  height: 132px;
  max-height: 160px;
  resize: none;
  font:
    12px/1.6 ui-monospace,
    monospace;
  color: var(--text);
  border: 1px solid var(--edge);
  border-radius: 5px;
  background: var(--panel);
  padding: 8px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.gb-copy-row {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-top: 8px;
}
.gb-copy-row span {
  font-size: 11px;
  color: var(--muted);
}
.gb-spin {
  animation: gb-spin 1.5s linear infinite;
}
@keyframes gb-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (max-width: 740px) {
  .gb-app {
    padding: 12px;
  }
  .gb-header {
    flex-wrap: wrap;
    gap: 10px;
  }
  .gb-brand {
    flex: 1;
    min-width: 0;
  }
  .gb-search {
    order: 4;
    flex: 1 1 100%;
    min-width: 0;
  }
  .gb-account {
    max-width: 190px;
  }
  .gb-workspace {
    grid-template-columns: 280px minmax(320px, 1fr);
    margin-top: 12px;
  }
  .gb-detail-scroll {
    padding: 20px;
  }
  .gb-detail-header {
    padding: 0 20px;
  }
  .gb-alert {
    right: 12px;
    top: 108px;
    width: calc(100% - 24px);
  }
}

